&lt;ul class=&quot;ak-ul&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1553&quot;&gt;Bachelor&#39;s degree in computer science, computer engineering or equivalent work experience&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;3+ years of work experience&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1628&quot;&gt;Fluency in Python&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1649&quot;&gt;Proficiency in Git&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1671&quot;&gt;Experience with CI/CD&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
