&lt;div class=&quot;_18s81h6l _1bsb1osq _p12fn7od&quot; data-testid=&quot;view-page-labels-container&quot; data-vc=&quot;view-page-labels-container&quot; data-ssr-placeholder=&quot;-JIDW:4y5Pz:qz-Pe:RPrst-0&quot;&gt;
&lt;div&gt;
&lt;div class=&quot; cc-1fum39a-container&quot;&gt;&lt;span id=&quot;react-select-2-live-region&quot; class=&quot;cc-19y6gjl-a11yText&quot;&gt;&lt;/span&gt;
&lt;div class=&quot;labels__control cc-1cu6367-control&quot;&gt;
